// seedProgressItem puts one item (id itm_<suffix>) in a fresh library and
// returns the item id — the write target for PutProgress.
func seedProgressItem(t *testing.T, s *Store, fileID string) string {
	t.Helper()
	ctx := context.Background()
	libID, err := s.CreateLibrary(ctx, "tv", "/media/progress-"+fileID, "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	itemID := "itm_" + fileID
	err = s.PutItem(ctx, Item{
		ID: itemID, ModuleID: "tv", LibraryID: libID, FileID: fileID,
		RelativePath: fileID + ".mkv", MediaType: "tv",
		Document: json.RawMessage(`{}`), SchemaVersion: 1,
	})
	if err != nil {
		t.Fatalf("PutItem %s: %v", fileID, err)
	}
	return itemID
}

// TestProgressUpsert covers the playback-progress upsert requirement: a second
// write for the same item overwrites the position and refreshes updated_at, so
// the table holds exactly ONE row per item with the latest values. Zero is a
// valid position (the CHECK is >= 0).
func TestProgressUpsert(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)
	itemID := seedProgressItem(t, s, "upsert")

	first, err := s.PutProgress(ctx, itemID, 30)
	if err != nil {
		t.Fatalf("PutProgress 30: %v", err)
	}
	time.Sleep(2 * time.Millisecond) // ensure a strictly later updated_at stamp
	second, err := s.PutProgress(ctx, itemID, 90)
	if err != nil {
		t.Fatalf("PutProgress 90: %v", err)
	}

	var rows int
	if err := s.db.QueryRowContext(ctx,
		"SELECT COUNT(*) FROM playback_progress WHERE item_id = ?", itemID).Scan(&rows); err != nil {
		t.Fatalf("count rows: %v", err)
	}
	if rows != 1 {
		t.Fatalf("rows for %s = %d, want 1 (upsert, not append)", itemID, rows)
	}
	got, err := s.GetProgress(ctx, itemID)
	if err != nil {
		t.Fatalf("GetProgress: %v", err)
	}
	if got.PositionSeconds != 90 {
		t.Fatalf("position = %d, want 90 (latest write wins)", got.PositionSeconds)
	}
	if got.UpdatedAt != second.UpdatedAt || got.UpdatedAt == first.UpdatedAt {
		t.Fatalf("updated_at = %q, want refreshed (first %q)", got.UpdatedAt, first.UpdatedAt)
	}

	t.Run("zero_position_allowed", func(t *testing.T) {
		if _, err := s.PutProgress(ctx, itemID, 0); err != nil {
			t.Fatalf("PutProgress 0: %v", err)
		}
	})
}

// TestPlaybackProgressReads covers the orphan-tolerant reads: rows whose item
// is gone (or deleted) are skipped — never an error — and the list carries
// only positive positions, newest-first.
func TestPlaybackProgressReads(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)
	a := seedProgressItem(t, s, "a")
	b := seedProgressItem(t, s, "b")
	c := seedProgressItem(t, s, "c")
	deleted := seedProgressItem(t, s, "gone")
	if _, err := s.db.ExecContext(ctx,
		"UPDATE items SET status = 'deleted' WHERE id = ?", deleted); err != nil {
		t.Fatalf("mark deleted: %v", err)
	}

	// Oldest → newest write order: c, a, b (plus the two invisible rows).
	for _, id := range []string{c, a, b} {
		if _, err := s.PutProgress(ctx, id, 100); err != nil {
			t.Fatalf("PutProgress %s: %v", id, err)
		}
		time.Sleep(2 * time.Millisecond)
	}
	if _, err := s.PutProgress(ctx, deleted, 100); err != nil {
		t.Fatalf("PutProgress deleted: %v", err)
	}
	// An orphaned row (item never existed) and a zero-position row are written
	// straight into the table: reads must skip both, never fail on them.
	if _, err := s.db.ExecContext(ctx,
		"INSERT INTO playback_progress (item_id, position_seconds, updated_at) VALUES ('itm_orphan', 50, ?)",
		formatTime(time.Now().UTC())); err != nil {
		t.Fatalf("seed orphan row: %v", err)
	}
	if _, err := s.PutProgress(ctx, a, 0); err != nil {
		t.Fatalf("PutProgress zero: %v", err)
	}

	t.Run("list_positive_newest_first", func(t *testing.T) {
		got, err := s.ListProgress(ctx, 20)
		if err != nil {
			t.Fatalf("ListProgress: %v", err)
		}
		want := []string{b, c} // a is zero, deleted + orphan skipped
		if len(got) != len(want) {
			t.Fatalf("ListProgress = %+v, want items %v", got, want)
		}
		for i, id := range want {
			if got[i].ItemID != id {
				t.Fatalf("ListProgress[%d] = %s, want %s (newest-first)", i, got[i].ItemID, id)
			}
		}
	})

	t.Run("get_orphan_is_absent", func(t *testing.T) {
		if _, err := s.GetProgress(ctx, "itm_orphan"); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("GetProgress orphan err = %v, want wrapped sql.ErrNoRows", err)
		}
	})

	t.Run("get_deleted_item_is_absent", func(t *testing.T) {
		if _, err := s.GetProgress(ctx, deleted); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("GetProgress deleted err = %v, want wrapped sql.ErrNoRows", err)
		}
	})
}

// TestPlaybackProgressSeconds_Migration covers the pre-phase-3 database path:
// a playback_progress table with the OLD placeholder shape (no
// position_seconds) gains the column on the next Open via the guarded ALTER,
// and a further Open stays safe (INV-idempotent-migration).
func TestPlaybackProgressSeconds_Migration(t *testing.T) {
	ctx := context.Background()
	dsn := filepath.Join(t.TempDir(), "legacy-progress.db")
	legacy, err := Open(ctx, dsn)
	if err != nil {
		t.Fatalf("Open legacy: %v", err)
	}
	if _, err := legacy.db.ExecContext(ctx, "DROP TABLE playback_progress"); err != nil {
		t.Fatalf("drop playback_progress: %v", err)
	}
	if _, err := legacy.db.ExecContext(ctx, `
CREATE TABLE playback_progress (
  item_id        TEXT NOT NULL,
  position_ms    INTEGER NOT NULL DEFAULT 0,
  duration_ms    INTEGER,
  played         INTEGER NOT NULL DEFAULT 0,
  play_count     INTEGER NOT NULL DEFAULT 0,
  last_played_at TEXT,
  updated_at     TEXT NOT NULL,
  PRIMARY KEY (item_id)
)`); err != nil {
		t.Fatalf("recreate placeholder shape: %v", err)
	}
	if _, err := legacy.db.ExecContext(ctx,
		"INSERT INTO playback_progress (item_id, updated_at) VALUES ('itm_legacy', ?)",
		formatTime(time.Now().UTC())); err != nil {
		t.Fatalf("seed legacy row: %v", err)
	}
	// The migrated row's item must exist for the write below to pass the
	// item-existence gate (PutProgress refuses unknown items).
	if err := legacy.PutItem(ctx, Item{
		ID: "itm_legacy", ModuleID: "tv", LibraryID: 1, FileID: "legacy",
		RelativePath: "legacy.mkv", MediaType: "tv",
		Document: json.RawMessage(`{}`), SchemaVersion: 1,
	}); err != nil {
		t.Fatalf("seed legacy item: %v", err)
	}
	if err := legacy.Close(); err != nil {
		t.Fatalf("Close legacy: %v", err)
	}

	reopened, err := Open(ctx, dsn)
	if err != nil {
		t.Fatalf("re-Open (guarded ALTER): %v", err)
	}
	defer reopened.Close()
	// A second re-Open must not error — the guarded ALTER no-ops.
	again, err := Open(ctx, dsn)
	if err != nil {
		t.Fatalf("second re-Open (idempotent): %v", err)
	}
	if err := again.Close(); err != nil {
		t.Fatalf("Close after second re-Open: %v", err)
	}
	if _, err := reopened.PutProgress(ctx, "itm_legacy", 42); err != nil {
		t.Fatalf("PutProgress on migrated table: %v", err)
	}
	got, err := reopened.GetProgress(ctx, "itm_legacy")
	if err != nil {
		t.Fatalf("GetProgress on migrated table: %v", err)
	}
	if got.PositionSeconds != 42 {
		t.Fatalf("position = %d, want 42", got.PositionSeconds)
	}
}
